mapper.sql:
SELECT uuid, current_worker_epoch, worker_lease_expires_at FROM code_sessions
WHERE organization_uuid = #{scope.OrganizationUUID} AND workspace_uuid = #{scope.WorkspaceUUID}
  AND uuid = #{scope.CodeSessionUUID} AND status = 'active' AND deleted_at IS NULL

mapper.select:
SELECT  FROM dsh_transcripts
WHERE  AND dsh_session_id = #{dshSessionID}
FOR UPDATE

SELECT  FROM dsh_transcripts
WHERE  AND dsh_session_id > #{after}
ORDER BY dsh_session_id LIMIT #{limit}

SELECT record_offset, payload FROM dsh_transcript_records
WHERE  AND transcript_uuid = #{transcriptUUID} AND record_offset >= #{fromOffset}
ORDER BY record_offset LIMIT #{limit}

WITH page AS (
    SELECT record_offset, octet_length(payload) AS size FROM dsh_transcript_records
    WHERE  AND transcript_uuid = #{transcriptUUID} AND record_offset >= #{fromOffset}
    ORDER BY record_offset LIMIT #{limit}
), chosen AS (
    SELECT record_offset FROM (
        SELECT record_offset, SUM(size) OVER (ORDER BY record_offset) - size AS preceding FROM page
    ) sized WHERE preceding < #{budget}
)
SELECT records.record_offset, records.payload FROM dsh_transcript_records AS records
JOIN chosen ON chosen.record_offset = records.record_offset
WHERE records.organization_uuid = #{scope.OrganizationUUID} AND records.workspace_uuid = #{scope.WorkspaceUUID}
  AND records.code_session_uuid = #{scope.CodeSessionUUID} AND records.transcript_uuid = #{transcriptUUID}
ORDER BY records.record_offset
